#include <iostream>
#include <limits>
#include <cstdlib>
#include "Student.h"
#include "Admin.h"
#include "RequestQueue.h"
#include "Rating.h"
#include "SkillTree.h"
#include "Graph.h"
#include "Matching.h"
using namespace std;
void clearInput(){cin.clear();cin.ignore(numeric_limits<streamsize>::max(),'\n');}
int readInt(const char* p,int a,int b){int x;while(true){cout<<p;if(cin>>x&&x>=a&&x<=b){clearInput();return x;}if(cin.eof())exit(0);cout<<"Invalid input.\n";clearInput();}}
void readText(const char* p,char* t,int n){cout<<p;cin.getline(t,n);}
void saveAll(StudentManager& s,RequestQueue& q,RatingSystem& r){s.saveToFile();q.saveToFile();r.saveToFile();}
const char* statusName(RequestStatus s){return s==PENDING?"Pending":s==ACCEPTED?"Accepted":"Rejected";}
void registerStudent(StudentManager& s,RequestQueue& q,RatingSystem& r){char n[60],b[40],u[30],p[30],skill[50];int id=readInt("Student ID: ",1,999999);readText("Name: ",n,60);readText("Branch: ",b,40);int sem=readInt("Semester: ",1,8);readText("Username: ",u,30);readText("Password: ",p,30);readText("Skill you can teach: ",skill,50);if(s.registerStudent(id,n,b,sem,u,p,skill)){saveAll(s,q,r);cout<<"Registration saved.\n";}else cout<<"Registration failed.\n";}
void showReceived(StudentManager& s,const RequestQueue& q,int receiver){LearningRequest a[MAX_REQUESTS];int c=q.getForReceiver(receiver,a,MAX_REQUESTS,true);if(!c){cout<<"No pending requests.\n";return;}for(int i=0;i<c;++i){Student* from=s.findById(a[i].senderId);cout<<a[i].id<<" | "<<(from?from->getName():"Unknown")<<" | "<<a[i].topic<<"\n";}}
void matchingMenu(Student* me,StudentManager& s,RequestQueue& q,RatingSystem& r,MatchingSystem& m){char skill[50];readText("Skill you want to learn: ",skill,50);Recommendation a[MAX_STUDENTS];int count=m.findMatches(me,s,skill,a,MAX_STUDENTS);if(!count){cout<<"No matching teacher found.\n";return;}for(int i=0;i<count;i++)cout<<i+1<<". "<<a[i].student->getName()<<" | "<<a[i].student->getTeachSkill()<<" | Score "<<a[i].score<<"\n";int pick=readInt("Send request to number (0 back): ",0,count);if(pick&&q.send(me->getId(),a[pick-1].student->getId(),skill)){saveAll(s,q,r);cout<<"Request sent.\n";}}
void studentMenu(Student* me,StudentManager& s,RequestQueue& q,RatingSystem& r,SkillTree& tree,StudentGraph& graph,MatchingSystem& m){while(true){cout<<"\n1.Profile\n2.Send request\n3.Respond requests\n4.Rate peer\n5.Add graph connection\n6.My graph connections\n7.View skill tree\n8.Get matches\n9.Logout\n";int c=readInt("Choice: ",1,9);if(c==1)me->displayProfile();else if(c==2){int id=readInt("Peer ID: ",1,999999);char topic[50];readText("Topic: ",topic,50);Student* peer=s.findById(id);if(peer&&!peer->isBanned()&&q.send(me->getId(),id,topic)){saveAll(s,q,r);cout<<"Request saved.\n";}else cout<<"Request failed.\n";}else if(c==3){showReceived(s,q,me->getId());int id=readInt("Request ID (0 back): ",0,999999);if(id){int reply=readInt("1.Accept 2.Reject: ",1,2);if(q.respond(id,me->getId(),reply==1)){saveAll(s,q,r);cout<<"Saved.\n";}else cout<<"Request not found.\n";}}else if(c==4){int id=readInt("Accepted peer ID: ",1,999999);Student* peer=s.findById(id);int score=readInt("Score 1-5: ",1,5);if(peer&&r.submit(me->getId(),*peer,score,q)){r.recalculate(s);saveAll(s,q,r);cout<<"Rating saved.\n";}else cout<<"Rating failed.\n";}else if(c==5){int id=readInt("Peer ID to connect: ",1,999999);cout<<(graph.connect(me->getId(),id)?"Connection added.\n":"Connection failed.\n");}else if(c==6)graph.display(me->getId());else if(c==7)tree.display();else if(c==8)matchingMenu(me,s,q,r,m);else return;}}
void showStudents(StudentManager& s){for(int i=0;i<s.getCount();++i){Student* x=s.getStudentAt(i);cout<<x->getId()<<" | "<<x->getName()<<" | "<<x->getAverageRating()<<" | "<<(x->isBanned()?"Banned":x->isFlagged()?"Flagged":"Active")<<"\n";}}
void showRequests(StudentManager& s,const RequestQueue& q){LearningRequest a[MAX_REQUESTS];int c=q.getAll(a,MAX_REQUESTS);if(!c){cout<<"No requests.\n";return;}for(int i=0;i<c;++i){Student* x=s.findById(a[i].senderId);Student* y=s.findById(a[i].receiverId);cout<<a[i].id<<" | "<<(x?x->getName():"Removed")<<" -> "<<(y?y->getName():"Removed")<<" | "<<a[i].topic<<" | "<<statusName(a[i].status)<<"\n";}}
void showRatings(StudentManager& s,const RatingSystem& r){RatingRecord a[MAX_STUDENTS];int c=r.getAll(a,MAX_STUDENTS);if(!c){cout<<"No ratings.\n";return;}for(int i=0;i<c;++i){Student* x=s.findById(a[i].raterId);Student* y=s.findById(a[i].ratedId);cout<<(x?x->getName():"Removed")<<" rated "<<(y?y->getName():"Removed")<<" "<<a[i].score<<"/5\n";}}
void adminMenu(StudentManager& s,RequestQueue& q,RatingSystem& r){while(true){cout<<"\n1.Students\n2.Requests\n3.Ratings\n4.Ban\n5.Unban\n6.Remove student\n7.Logout\n";int c=readInt("Choice: ",1,7);if(c==1)showStudents(s);else if(c==2)showRequests(s,q);else if(c==3)showRatings(s,r);else if(c==4||c==5){Student* x=s.findById(readInt("Student ID: ",1,999999));if(x){x->setManualBanned(c==4);x->setFlagged(c==4);saveAll(s,q,r);cout<<"Status updated.\n";}else cout<<"Not found.\n";}else if(c==6){int id=readInt("Student ID: ",1,999999);if(s.findById(id)&&readInt("1.Remove 2.Cancel: ",1,2)==1){q.removeForStudent(id);r.removeForStudent(id);s.removeById(id);r.recalculate(s);saveAll(s,q,r);cout<<"Removed.\n";}}else return;}}
void addDemoData(StudentManager& s,RequestQueue& q,RatingSystem& r){if(s.getCount())return;s.registerStudent(101,"Aarav Sharma","CSE",3,"aarav","pass123","C++");s.registerStudent(102,"Diya Singh","CSE",4,"diya","pass123","Python");s.registerStudent(103,"Kabir Khan","CSE",3,"kabir","pass123","Data Structures");saveAll(s,q,r);cout<<"Demo students added. Login: aarav/pass123, diya/pass123, kabir/pass123\n";}
int main(){StudentManager s;RequestQueue q;RatingSystem r;Admin a;SkillTree tree;StudentGraph graph;MatchingSystem m;s.loadFromFile();q.loadFromFile();r.loadFromFile();addDemoData(s,q,r);r.recalculate(s);tree.loadDefaultSkills();for(int i=0;i<s.getCount();++i)graph.addStudent(s.getStudentAt(i)->getId());while(true){cout<<"\n1.Register\n2.Student login\n3.Admin login\n4.Exit\n";int c=readInt("Choice: ",1,4);if(c==1){registerStudent(s,q,r);if(s.getCount())graph.addStudent(s.getStudentAt(s.getCount()-1)->getId());}else if(c==2){char u[30],p[30];readText("Username: ",u,30);readText("Password: ",p,30);Student* x=s.login(u,p);if(x&&!x->isBanned())studentMenu(x,s,q,r,tree,graph,m);else cout<<"Invalid login or banned.\n";}else if(c==3){char u[30],p[30];readText("Admin username: ",u,30);readText("Admin password: ",p,30);if(a.login(u,p))adminMenu(s,q,r);else cout<<"Invalid admin.\n";}else{saveAll(s,q,r);cout<<"All data saved.\n";return 0;}}}
